'use strict';
/* ---------- the company muster: live army groups, their condition and the people travelling with them ---------- */
const partyView=()=>G.partyUI||(G.partyUI={tab:'army',sel:'hero',open:false,status:false});
const partyBack=()=>{const s=partyView();return s.status||s.open&&fbNarrow()||G.armyEdit?['party-back',null,'Back']:null};
function partyGroup(id,r=partyRoster(P)){const g=r.groups.find(g=>g.id===id),w=(P.woundedGroups||[]).find(g=>g.id===id),cid=id.startsWith('comp_')?id.slice(5):null,c=cid&&P.comps[cid],type=g?.type||w?.type,hurt=c&&c.hurt>G.day;
  return{id,g,cid,type,name:armyGroupLabel(id,r),fit:g?g.count:id==='hero'?1:c&&!hurt?1:0,wounded:type?r.wounded(id):hurt?1:0,pic:portrait(type||cid||'hero',id==='hero'),sub:type?ST[type].n:cid?'Companion':'Your hero',hurt};
}
function partyCard(id,r,index){const g=partyGroup(id,r),on=partyView().sel===id,word=g.wounded?' wounded':'',share=g.fit/Math.max(1,g.fit+g.wounded)*100;
  return '<button type="button" class="fb-unit'+(on?' on':'')+'" data-army-group="'+id+'" data-act="party-select" data-arg="'+id+'" aria-pressed="'+on+'"><span class="fb-unit-key">'+(g.hurt||!g.fit?'—':index)+'</span><span class="fb-unit-kind">'+fbIcon(g.type?'troops':'hero',14)+htmlText(g.type?classN(ST[g.type]):g.sub)+'</span><img src="'+g.pic+'" alt=""><strong>'+htmlText(g.name)+'</strong><small>'+htmlText(g.sub)+'</small><span class="fb-unit-count">'+fbIcon('troops',14)+'<b>'+g.fit+'</b> fit<span class="grow"></span>'+fbIcon('wounded',14)+'<b>'+g.wounded+'</b>'+word+'</span><span class="fb-bar"><i style="width:'+share+'%"></i></span></button>';
}
function partyBanner(){const S=supplyNow(),F=bandFitness(),r=partyRoster(P);return '<button type="button" class="fb-muster" data-act="party-status" aria-label="Army condition: Fitness '+Math.round(F.pct)+'%, Morale '+Math.round(P.morale)+'%, Stamina '+Math.round(P.bsta)+'%. Details"><span class="fb-standard" aria-hidden="true"></span><span class="fb-company"><small>Company muster</small><strong>'+htmlText(bandName())+'</strong><small>'+r.slots+' / '+ARMY_LIMIT+' groups · '+F.fit+' fit + hero · '+F.wounded+' wounded</small></span><span class="fb-muster-meters">'+fbMeter('shield','Fitness',F.pct,100,F.pct<50?'bad':'')+fbMeter('morale','Morale',P.morale,100,P.morale<30?'warn':'')+fbMeter('speed','Stamina',P.bsta,100,S.st==='fresh'?'':'warn')+'<span class="fb-muster-note">'+(S.tags.length?S.tags.slice(0,2).map(([n])=>htmlText(n)).join(' · '):'On the road')+(S.drinkDays<1?' · Low drink':'')+'<b>Details ›</b></span></span></button>'}
function partyCondition(){const S=supplyNow(),F=bandFitness(),r=partyRoster(P),d=n=>Number.isFinite(n)?(Math.floor(n*10)/10)+'d':'—';return '<section class="fb-pane fb-condition"><div class="fb-pane-head"><h3>Army condition</h3><span>'+htmlText(S.st)+'</span></div><div class="fb-scroll" data-fb-scroll="army-condition"><div class="fb-condition-meters">'+fbMeter('shield','Fitness',F.pct,100,F.pct<50?'bad':'')+fbMeter('morale','Morale',P.morale,100,P.morale<30?'warn':'')+fbMeter('speed','Stamina',P.bsta,100,S.st==='fresh'?'':'warn')+'</div><div class="fb-condition-tags">'+S.tags.map(([n,c,why])=>'<details class="fb-tag '+c+'"><summary>'+htmlText(n)+'</summary><p>'+htmlText(why)+'</p></details>').join('')+'</div><div class="fb-condition-facts">'+fbStat('troops','Fit fighters',F.fit+1)+fbStat('wounded','Wounded',F.wounded)+fbStat('banner','Groups',r.slots+' / '+ARMY_LIMIT)+fbStat('power','Power',partyPower())+fbStat('food','Food',d(S.foodDays))+fbStat('mug','Drink',d(S.drinkDays),S.drinkDays<1?'warn':'')+fbStat('people','Headcount',partySize()+' / '+partyCap())+fbStat('gold','Gold',P.gold)+'</div>'+partyPowerParts()+'<div class="fb-recovery">'+fbIcon('fire',24)+'<b>Stamina '+(S.r.n>=0?'+':'')+Math.round(S.r.n*10)/10+' / hour</b><span>'+htmlText(S.r.why.join(' · '))+'</span></div>'+fbDetails('Condition and recovery','<p>Fitness includes the fit, wounded, companions and your hero’s health ('+Math.round(F.hp*100)+'%). Power is a separate combat estimate.</p><p>Camp restores '+SUPPLY.rest.camp+' stamina per hour and wounded heal faster. Tired below '+SUPPLY.tired+'%; Exhausted below '+SUPPLY.exhausted+'%. Return to the map to camp safely. Supply days use the current consumption rate.</p>'+woundedPanel())+'<div class="fb-details"><h3>Recruitment target</h3><p>'+htmlText(G.recruitTarget==='new'?'Create a new group':r.groups.some(g=>g.id===G.recruitTarget)?armyGroupLabel(G.recruitTarget,r):'Auto reinforce')+'</p><div class="btns">'+fbBtn('army-recruit','new','New recruit group',r.slots>=ARMY_LIMIT?'No free group':'')+fbBtn('army-recruit','','Auto reinforce')+'</div></div></div><div class="fb-actions">'+fbBtn('party-supplies',null,fbIcon('bag')+'Supplies')+fbBtn('party-back',null,'Back to army','','primary')+'</div></section>'}
// party power by fighter: your hero, each companion and each troop type, strongest first
function partyPowerParts(){const tr=Object.keys(P.troops).filter(k=>P.troops[k]>0),total=partyPower(),parts=[[P.name?htmlText(P.name):'You','Level '+P.level+' hero',rating(['hero'])],...Object.keys(P.comps).map(id=>[COMPS[id].n,'Companion',rating([id])]),...tr.map(k=>[ST[k].n,P.troops[k]+' × '+rating([k]),rating(Array(P.troops[k]).fill(k))])].sort((a,b)=>b[2]-a[2]);
  return fbDetails('Party power · '+total,parts.map(([n,sub,v])=>'<div class="row"><div class="info"><strong>'+n+'</strong><small>'+sub+'</small><div class="bar" aria-hidden="true"><i style="width:'+Math.round(v/Math.max(1,total)*100)+'%"></i></div></div><span class="own">'+v+'</span></div>').join('')+'<p class="muted">Each fighter counts as the square root of health × damage per second, added up across your band. Compare it with the number shown before each fight.'+(skill('tact')?' Tactics also adds '+5*skill('tact')+'% when you auto-resolve.':'')+'</p>')}
function partyGroupEditor(id,r){const g=r.groups.find(g=>g.id===id),name=r.nameOf(id),full=r.slots>=ARMY_LIMIT,at=r.order.indexOf(id);return '<div class="army-editor" data-army-editor="'+id+'">'+(G.armyNotice?'<p role="status">'+htmlText(G.armyNotice)+'</p>':'')+'<label>Group name<input data-army-name maxlength="32" value="'+htmlText(name)+'" placeholder="'+htmlText(armyGroupLabel(id,r))+'"></label><div class="btns">'+fbBtn('army-name-save',id,'Save name')+fbBtn('army-name-reset',id,'Use default')+'</div><div class="fb-edit-actions">'+fbBtn('army-move',id+':-1','↑ Move up',at<=0?'First in order':'')+fbBtn('army-move',id+':1','↓ Move down',at<0||at>=r.order.length-1?'Last in order':'')+'</div>'+(g?fbQuantity(Math.max(1,Math.floor(g.count/2)),Math.max(1,g.count-1),'data-army-split')+'<div class="btns">'+fbBtn('army-split-exact',id,'Split this number',full||g.count<2?'Needs a free group and two fit soldiers':'')+fbBtn('party-merge',id,'Merge group',r.groups.some(o=>o.id!==id&&o.type===g.type)?'':'No matching group')+'</div><small>Only fit soldiers split. Wounded stay with '+htmlText(armyGroupLabel(id,r))+'.</small>':'')+'</div>'}
function partyInspector(id,r){const u=partyGroup(id,r),ch=!u.type?(u.cid?charOf(compInit(u.cid),u.cid):charOf(P,'hero')):null,st=u.type?ST[u.type]:ch&&ch.stats(),mor=Math.round(unitMoraleOf(st)),now=Math.round(clamp(mor*(.6+.4*clamp(P.morale,0,100)/100),20,100));
  return '<section class="fb-pane fb-inspector"><div class="fb-scroll" data-fb-scroll="army:'+id+'"><div class="fb-figure"><img src="'+u.pic+'" alt=""></div><div class="fb-title"><small>'+htmlText(u.sub)+'</small><h3>'+htmlText(u.name)+'</h3></div><div class="fb-stat-grid">'+fbStat('troops','Fit',u.fit)+fbStat('wounded','Wounded',u.wounded)+fbStat('wounded',u.type?'Health each':'Health',u.type?st.hp:(u.cid?(u.hurt?0:st.hp):Math.round(P.hp))+' / '+st.hp)+fbStat('sword','Attack',u.type?meleeDmgOf(st):Math.round(st?.dmg||0))+(u.type?fbStat('eye','Missile',missileDmgOf(st)||'—')+(st.range?fbStat('region','Range',st.range):fbStat('shield','Armour',ARMOR[armorOf(st)].n)):'')+'</div>'+fbMeter('banner','Battle morale',now,mor)+(u.type&&UP[u.type]?fbMeter('skills','Training · all '+ST[u.type].n,txpOf(u.type),Math.max(1,(P.troops[u.type]||0)*txpNeed(u.type)))+'<p class="fb-training-note">'+txpReady(u.type)+' ready to train at a barracks</p>':'')+(G.armyEdit===id?partyGroupEditor(id,r):fbDetails('Group details','<p>'+htmlText(u.type?vsLine(st):'Your character occupies one army slot.')+'</p><p>Wounded remain with their group; recovering groups with no fit soldiers wait for a free slot.</p>'))+'</div><div class="fb-actions">'+fbBtn(G.armyEdit===id?'army-edit-close':'army-edit',id,G.armyEdit===id?'Done':fbIcon('book')+'Manage group','','primary')+(u.g?fbBtn('army-recruit',id,'Reinforce'):'')+'</div></section>';
}
function partyCompCards(){return Object.keys(P.comps).map(id=>{const c=compInit(id);return '<button type="button" class="fb-person" data-act="cm-open" data-arg="'+id+'"><small>Lv. '+c.lv+'</small><img src="'+portrait(id)+'" alt=""><strong>'+htmlText(COMPS[id].short)+'</strong><span>'+fbIcon(c.role==='scout'?'eye':c.role==='surgeon'?'wounded':'hero')+htmlText(c.role?ROLES[c.role]:'No role')+'</span>'+(c.party?'<span>Leading '+c.party.troops.length+'</span>':c.hurt>G.day?'<span class="bad">Wounded until '+c.hurt+'</span>':'')+(c.tp?'<b class="gold">'+fbIcon('skills',14)+' '+c.tp+'</b>':'')+'</button>'}).join('')}
function partyPrisoners(){return Object.keys(P.prisoners).filter(k=>P.prisoners[k]>0).map(k=>{const q=recruitment.quotePrisoner(k);return '<div class="fb-prisoner"><img src="'+portrait(k)+'" alt=""><div><strong>'+htmlText(ST[k].n)+'</strong><small>'+P.prisoners[k]+' prisoners · Ransom '+RANSOM[ST[k].tier]+'g each</small>'+(!q.ok?'<small class="bad">'+htmlText(recruitmentWhy(q))+'</small>':'')+'</div><div class="btns">'+fbBtn('p-recruit',k,'Recruit '+q.cost+'g',q.ok?'':recruitmentWhy(q))+fbBtn('p-release',k,'Release')+'</div></div>'}).join('')||'<p class="muted">No prisoners. Win battles to take some.</p>'}
function partyPage(){vitals();const s=partyView(),r=partyRoster(P);if(G.armyEdit){s.sel=G.armyEdit;s.open=true}const tabs=fbTabs([['army','Army'],['companions','Companions'],['passengers','Passengers'],['prisoners','Prisoners']],s.tab,'party-tab','Party sections');let body='';
  if(s.tab==='army'){if(s.status)body=partyCondition();else{const recover=[...new Set((P.woundedGroups||[]).filter(w=>w.count>0&&!r.groups.some(g=>g.id===w.id)).map(w=>w.id))],ids=[...r.order,...recover];if(!ids.includes(s.sel))s.sel=ids[0];let key=0;body='<div class="fb-army-layout'+(s.open?' open':'')+'">'+partyBanner()+'<div class="fb-split"><section class="fb-pane fb-collection"><div class="fb-pane-head"><h3>Battle order</h3><span>'+r.slots+' / '+ARMY_LIMIT+'</span></div><div class="fb-scroll fb-unit-grid" data-fb-scroll="army-roster">'+r.order.map(id=>{const g=partyGroup(id,r);return partyCard(id,r,g.hurt?'—':++key%10)}).join('')+(recover.length?'<div class="fb-section">Recovering groups · no fit soldiers</div>'+recover.map(id=>partyCard(id,r,'—')).join(''):'')+'</div><div class="fb-recruit-options">'+fbBtn('army-recruit','new','New recruit group',r.slots>=ARMY_LIMIT?'No free group':'')+fbBtn('army-recruit','','Auto reinforce')+'</div></section>'+(s.sel?partyInspector(s.sel,r):'')+'</div></div>'}}
  else if(s.tab==='companions')body='<div class="fb-scroll fb-portrait-grid" data-fb-scroll="companions">'+(partyCompCards()||'<p class="muted">Find companions in town taverns.</p>')+'</div>';
  else if(s.tab==='passengers')body='<div class="fb-scroll" data-fb-scroll="passengers">'+(Escort.html()||'<p class="muted">No passengers. Escort quests bring them.</p>')+'</div>';
  else body='<div class="fb-scroll" data-fb-scroll="prisoners">'+'<h3>Prisoners '+prisonerCount()+' / '+prisonCap()+'</h3>'+partyPrisoners()+captivesHtml()+'</div>';
  return '<div class="fb-party">'+tabs+body+'</div>';
}
onAct('party-',(a,arg)=>{
  if(typeof companionPageAct==='function'&&companionPageAct(a,arg))return;
  if(G.mode!=='char')return;const s=partyView();fbRemember();
  if(a==='party-tab'&&['army','companions','passengers','prisoners'].includes(arg)){s.tab=arg;s.open=false;s.status=false;G.armyEdit=null}
  else if(a==='party-select'){s.sel=arg;s.open=true;s.status=false;G.armyEdit=null}
  else if(a==='party-back'){if(s.status)s.status=false;else if(G.armyEdit)G.armyEdit=null;else s.open=false}
  else if(a==='party-status')s.status=true;
  else if(a==='party-supplies'){G.mode='world';hidePanel();openInv();G.invTab='supplies';renderInv();return}
  else if(a==='party-merge'){const r=partyRoster(P),g=r.groups.find(g=>g.id===arg);if(!g)return;fbChoose({title:'Merge into matching group',value:null,items:r.groups.filter(o=>o.id!==arg&&o.type===g.type).map(o=>({id:o.id,name:armyGroupLabel(o.id,r),sub:o.count+' fit · '+r.wounded(o.id)+' wounded',pic:portrait(o.type)})),back:renderChar,apply:id=>{G.armyMergeTarget=id;charAct('army-merge-picked',arg)}});return}
  else return;renderChar();
});
